import React, { useState, useRef } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [mode, setMode] = useState("fast");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const summaryRef = useRef(null);

  // 🚀 MAIN LOGIC (CONNECTED TO PYTHON)
  const handleSearch = async () => {
    const queryKey = `${disease}-${intent}-${location}`;

    if (!disease && !intent) {
      alert("Enter something");
      return;
    }

    setLoading(true);

    // ⚡ FRONTEND CACHE (VERY FAST)
    const cached = localStorage.getItem(queryKey);
    if (cached) {
      const data = JSON.parse(cached);
      setSummary(data.summary);
      setPublications(data.publications);
      setTrials(data.trials);
      setLoading(false);
      return;
    }

    // ⚡ FAST MODE (NO API CALL)
    if (mode === "fast") {
      const fastData = {
        summary: `Quick AI Overview:

• ${disease || "Condition"} requires proper diagnosis  
• Early treatment improves outcomes  
• Lifestyle + medication recommended  

(Use Deep Mode for full research)`,

        publications: [],
        trials: [],
      };

      setSummary(fastData.summary);
      setPublications([]);
      setTrials([]);

      localStorage.setItem(queryKey, JSON.stringify(fastData));

      setLoading(false);
      return;
    }

    // 🔬 DEEP MODE (CALL PYTHON API)
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 10000);

      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      const data = await res.json();

      const result = {
        summary: data.insights || "",
        publications: data.publications || [],
        trials: data.clinical_trials || [],
      };

      setSummary(result.summary);
      setPublications(result.publications);
      setTrials(result.trials);

      // ⚡ cache result
      localStorage.setItem(queryKey, JSON.stringify(result));

      setTimeout(() => {
        summaryRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 200);

    } catch (err) {
      console.error(err);
      setSummary("⚠️ Backend slow. Try Fast Mode.");
    }

    setLoading(false);
  };

  return (
    <div className="app">

      {/* LEFT */}
      <div className="sidebar">
        <h1>Curalink X</h1>

        <input
          placeholder="Disease..."
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="mode-toggle">
          <button onClick={() => setMode("fast")}>⚡ Fast</button>
          <button onClick={() => setMode("deep")}>🔬 Deep</button>
        </div>
      </div>

      {/* CENTER */}
      <div className="main">
        <textarea
          placeholder="Ask medical question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        <button onClick={handleSearch}>
          {loading ? "⏳ Loading..." : "Search"}
        </button>

        {summary && (
          <div ref={summaryRef}>
            {summary.split("\n").map((line, i) => (
              <p key={i}>{line}</p>
            ))}
          </div>
        )}
      </div>

      {/* RIGHT */}
      <div className="right">
        <h3>Papers</h3>
        {publications.map((p, i) => (
          <p key={i}>{p.title}</p>
        ))}

        <h3>Trials</h3>
        {trials.map((t, i) => (
          <p key={i}>{t.title}</p>
        ))}
      </div>

    </div>
  );
}

export default App;
